// Package wire converts Go values to and from DynamoDB attribute values for
// code generated by wattdb. Applications don't use it directly.
//
// Encoders return a nil value for "missing" (an empty set, decision D18).
package wire

import (
	"fmt"
	"reflect"
	"strconv"

	"github.com/aws/aws-sdk-go-v2/feature/dynamodb/attributevalue"
	"github.com/aws/aws-sdk-go-v2/service/dynamodb/types"
)

// Encoder converts a T to an attribute value.
type Encoder[T any] func(T) (types.AttributeValue, error)

// Decoder converts an attribute value to a T.
type Decoder[T any] func(types.AttributeValue) (T, error)

func EncodeString(v string) (types.AttributeValue, error) {
	return &types.AttributeValueMemberS{Value: v}, nil
}

func EncodeEnum[T ~string](v T) (types.AttributeValue, error) {
	return &types.AttributeValueMemberS{Value: string(v)}, nil
}

func EncodeInt[T ~int | ~int64](v T) (types.AttributeValue, error) {
	return &types.AttributeValueMemberN{Value: strconv.FormatInt(int64(v), 10)}, nil
}

// EncodeNumber encodes any number type (set and list items).
func EncodeNumber[T ~int | ~int64 | ~float64](v T) (types.AttributeValue, error) {
	return &types.AttributeValueMemberN{Value: formatNumber(v)}, nil
}

// EncodeFloat formats like strconv 'f' (decision D56), writing -0 as "0".
func EncodeFloat(v float64) (types.AttributeValue, error) {
	return &types.AttributeValueMemberN{Value: FormatFloat(v)}, nil
}

// FormatFloat is the number formatting wattdb uses for float64.
func FormatFloat(v float64) string {
	if v == 0 {
		return "0"
	}
	return strconv.FormatFloat(v, 'f', -1, 64)
}

func EncodeBool(v bool) (types.AttributeValue, error) {
	return &types.AttributeValueMemberBOOL{Value: v}, nil
}

// EncodeStringSet encodes a string set; an empty set is missing.
func EncodeStringSet[T ~string](vs []T) (types.AttributeValue, error) {
	if len(vs) == 0 {
		return nil, nil
	}
	out := make([]string, len(vs))
	for i, v := range vs {
		out[i] = string(v)
	}
	return &types.AttributeValueMemberSS{Value: out}, nil
}

// EncodeNumberSet encodes a number set; an empty set is missing.
func EncodeNumberSet[T ~int | ~int64 | ~float64](vs []T) (types.AttributeValue, error) {
	if len(vs) == 0 {
		return nil, nil
	}
	out := make([]string, len(vs))
	for i, v := range vs {
		out[i] = formatNumber(v)
	}
	return &types.AttributeValueMemberNS{Value: out}, nil
}

func formatNumber[T ~int | ~int64 | ~float64](v T) string {
	switch x := any(v).(type) {
	case float64:
		return FormatFloat(x)
	default:
		if reflect.TypeOf(v).Kind() == reflect.Float64 {
			return FormatFloat(reflect.ValueOf(v).Float())
		}
		return strconv.FormatInt(reflect.ValueOf(v).Int(), 10)
	}
}

// ListEncoder encodes a list item by item.
func ListEncoder[T any](item Encoder[T]) Encoder[[]T] {
	return func(vs []T) (types.AttributeValue, error) {
		out := make([]types.AttributeValue, 0, len(vs))
		for i, v := range vs {
			av, err := item(v)
			if err != nil {
				return nil, fmt.Errorf("[%d]: %w", i, err)
			}
			if av != nil {
				out = append(out, av)
			}
		}
		return &types.AttributeValueMemberL{Value: out}, nil
	}
}

// EncodeAny encodes any Go value with attributevalue.
func EncodeAny(v any) (types.AttributeValue, error) {
	return attributevalue.Marshal(v)
}

// EncodeAnyOf encodes a T with attributevalue.
func EncodeAnyOf[T any](v T) (types.AttributeValue, error) {
	return attributevalue.Marshal(v)
}

func DecodeString(av types.AttributeValue) (string, error) {
	s, ok := av.(*types.AttributeValueMemberS)
	if !ok {
		return "", mismatch("string", av)
	}
	return s.Value, nil
}

func DecodeEnum[T ~string](av types.AttributeValue) (T, error) {
	s, err := DecodeString(av)
	return T(s), err
}

func DecodeInt[T ~int | ~int64](av types.AttributeValue) (T, error) {
	n, ok := av.(*types.AttributeValueMemberN)
	if !ok {
		return 0, mismatch("number", av)
	}
	i, err := strconv.ParseInt(n.Value, 10, 64)
	if err != nil {
		f, ferr := strconv.ParseFloat(n.Value, 64)
		if ferr != nil || f != float64(int64(f)) {
			return 0, fmt.Errorf("wire: %q isn't an integer", n.Value)
		}
		i = int64(f)
	}
	return T(i), nil
}

func DecodeFloat(av types.AttributeValue) (float64, error) {
	n, ok := av.(*types.AttributeValueMemberN)
	if !ok {
		return 0, mismatch("number", av)
	}
	return strconv.ParseFloat(n.Value, 64)
}

func DecodeBool(av types.AttributeValue) (bool, error) {
	b, ok := av.(*types.AttributeValueMemberBOOL)
	if !ok {
		return false, mismatch("boolean", av)
	}
	return b.Value, nil
}

// DecodeStringSet decodes a string set, or a list of strings (what a set
// attribute holds when read back through ElectroDB's getters).
func DecodeStringSet[T ~string](av types.AttributeValue) ([]T, error) {
	switch v := av.(type) {
	case *types.AttributeValueMemberSS:
		out := make([]T, len(v.Value))
		for i, s := range v.Value {
			out[i] = T(s)
		}
		return out, nil
	case *types.AttributeValueMemberL:
		return ListDecoder(DecodeEnum[T])(v)
	default:
		return nil, mismatch("string set", av)
	}
}

// DecodeNumberSet decodes a number set, or a list of numbers.
func DecodeNumberSet[T ~int | ~int64 | ~float64](av types.AttributeValue) ([]T, error) {
	var strs []string
	switch v := av.(type) {
	case *types.AttributeValueMemberNS:
		strs = v.Value
	case *types.AttributeValueMemberL:
		for _, e := range v.Value {
			n, ok := e.(*types.AttributeValueMemberN)
			if !ok {
				return nil, mismatch("number", e)
			}
			strs = append(strs, n.Value)
		}
	default:
		return nil, mismatch("number set", av)
	}
	out := make([]T, len(strs))
	for i, s := range strs {
		var zero T
		if reflect.TypeOf(zero).Kind() == reflect.Float64 {
			f, err := strconv.ParseFloat(s, 64)
			if err != nil {
				return nil, err
			}
			reflect.ValueOf(&out[i]).Elem().SetFloat(f)
		} else {
			n, err := DecodeInt[int64](&types.AttributeValueMemberN{Value: s})
			if err != nil {
				return nil, err
			}
			reflect.ValueOf(&out[i]).Elem().SetInt(n)
		}
	}
	return out, nil
}

// ListDecoder decodes a list item by item.
func ListDecoder[T any](item Decoder[T]) Decoder[[]T] {
	return func(av types.AttributeValue) ([]T, error) {
		l, ok := av.(*types.AttributeValueMemberL)
		if !ok {
			return nil, mismatch("list", av)
		}
		out := make([]T, 0, len(l.Value))
		for i, e := range l.Value {
			v, err := item(e)
			if err != nil {
				return nil, fmt.Errorf("[%d]: %w", i, err)
			}
			out = append(out, v)
		}
		return out, nil
	}
}

// DecodeAny decodes into a plain Go value with attributevalue.
func DecodeAny(av types.AttributeValue) (any, error) {
	var v any
	err := attributevalue.Unmarshal(av, &v)
	return v, err
}

// DecodeAnyOf decodes into a T with attributevalue.
func DecodeAnyOf[T any](av types.AttributeValue) (T, error) {
	var v T
	err := attributevalue.Unmarshal(av, &v)
	return v, err
}

// DecodeMap returns a map value's members.
func DecodeMap(av types.AttributeValue) (map[string]types.AttributeValue, error) {
	m, ok := av.(*types.AttributeValueMemberM)
	if !ok {
		return nil, mismatch("map", av)
	}
	return m.Value, nil
}

// Ptr decodes an optional value: nil (missing) stays nil.
func Ptr[T any](av types.AttributeValue, dec Decoder[T]) (*T, error) {
	if av == nil {
		return nil, nil
	}
	v, err := dec(av)
	if err != nil {
		return nil, err
	}
	return &v, nil
}

// FromPtr encodes an optional value: nil stays missing.
func FromPtr[T any](v *T, enc Encoder[T]) (types.AttributeValue, error) {
	if v == nil {
		return nil, nil
	}
	return enc(*v)
}

// Convert converts a schema default (e.g. an untyped constant) to T.
func Convert[T any](v any) (T, error) {
	var zero T
	if t, ok := v.(T); ok {
		return t, nil
	}
	rv := reflect.ValueOf(v)
	target := reflect.TypeOf(zero)
	if !rv.IsValid() || target == nil || !rv.Type().ConvertibleTo(target) {
		return zero, fmt.Errorf("wire: can't use %T as %T", v, zero)
	}
	return rv.Convert(target).Interface().(T), nil
}

func mismatch(want string, av types.AttributeValue) error {
	return fmt.Errorf("wire: expected a %s, got %T", want, av)
}

// SiblingList rebuilds a list from the siblings a list item's callbacks
// receive (keyed by index).
func SiblingList[T any](sib map[string]types.AttributeValue, dec Decoder[T]) ([]T, error) {
	out := make([]T, len(sib))
	for k, av := range sib {
		i, err := strconv.Atoi(k)
		if err != nil || i < 0 || i >= len(out) {
			return nil, fmt.Errorf("wire: bad list sibling key %q", k)
		}
		v, err := dec(av)
		if err != nil {
			return nil, err
		}
		out[i] = v
	}
	return out, nil
}
